      <TextInput
        style={[stiller.girdi, odakli && stiller.girdiOdakli]}
        placeholder={t('kayit.telefonYerTutucu')}
        placeholderTextColor={renk.metinSoluk}
        keyboardType="phone-pad"
        autoComplete="tel"
        value={telefon}
        onChangeText={(yeni) => {
          setTelefon(yeni)
          setHata(null)
        }}
