import { useEffect, useRef, useState } from 'react'
import {
  View,
  Text,
  TextInput,
  Pressable,
  ScrollView,
  Image,
  StyleSheet,
} from 'react-native'
import { useRouter } from 'expo-router'
import Svg, { Path, Circle } from 'react-native-svg'
import * as ImagePicker from 'expo-image-picker'
import { supabase } from '../../lib/supabase'
import { onSekizAltindaMi } from '../../lib/yas'
import { fotografYukle } from '../../lib/fotograf-yukle'
import { useOturum } from '../../lib/oturum'
import { useDil } from '../../lib/dil'
import {
  kullaniciAdiGecerliMi,
  kullaniciAdiniNormallestir,
  kullaniciAdiMusaitMi,
} from '../../lib/kullanici-adi'
import { renk, yazi, olcek, bosluk, yuvarlak, golge } from '../tasarim/tema'

/** En fazla kac fotograf secilebilir. Ilki profil fotografi olur. */
const EN_FAZLA_FOTOGRAF = 6

/** Kullanici adi musaitlik sorgusunun bekletme suresi. */
const BEKLETME_MS = 300

/** Hata metinlerinin rengi - kimlik paletinde bir hata tonu yok. */
const HATA_RENGI = '#C0392B'

type AdDurumu =
  | { hal: 'bos' }
  | { hal: 'bicim' }
  | { hal: 'kontrol' }
  | { hal: 'musait' }
  | { hal: 'alinmis' }

/**
 * Profil olusturma - kayit akisinin son adimi.
 *
 * Bu ekrandan once telefon dogrulanmis oluyor, yani hesap zaten var;
 * burada eksik olan tek sey profil satiri. Ekrani goren kisi
 * uygulamanin ICINE bakmis degil, dolayisiyla her alanin ne ise
 * yaradigi yazili olmali - yer tutucu tek basina etiket sayilmaz
 * (yazmaya baslayinca kayboluyor).
 *
 * Dogum tarihi UC AYRI ALAN: tek satirda "YYYY-AA-GG" istemek
 * kullaniciya bicim ezberletmek demekti ve ekranda bunun dogru olup
 * olmadigini anlamanin yolu yoktu. Ay alaninda ad degil sayi
 * isteniyor; ad listesi ceviriyle birlikte 12 satir daha buyuyor ve
 * rakam her dilde ayni.
 *
 * Kullanici adi musaitligi BEKLETMELI sorgulaniyor ve gec donen cevap
 * sira numarasiyla eleniyor; yoksa hizli yazan birinde ekranda onceki
 * harfin sonucu kalabiliyor.
 */
export default function ProfilOlusturEkrani() {
  const router = useRouter()
  const { t } = useDil()
  const { profilKontrolunuYenile } = useOturum()

  const [ad, setAd] = useState('')
  const [kullaniciAdi, setKullaniciAdi] = useState('')
  const [adDurumu, setAdDurumu] = useState<AdDurumu>({ hal: 'bos' })
  const [gun, setGun] = useState('')
  const [ay, setAy] = useState('')
  const [yil, setYil] = useState('')
  const [biyografi, setBiyografi] = useState('')
  const [fotografUrileri, setFotografUrileri] = useState<string[]>([])

  const [alanHatalari, setAlanHatalari] = useState<Record<string, string | null>>({})
  const [hata, setHata] = useState<string | null>(null)
  const [gonderiliyor, setGonderiliyor] = useState(false)
  const [odakli, setOdakli] = useState<string | null>(null)

  const ayRef = useRef<TextInput>(null)
  const yilRef = useRef<TextInput>(null)
  // Gec donen musaitlik cevaplarini elemek icin sira numarasi.
  const sorguSirasi = useRef(0)

  function alanHatasiniTemizle(alan: string) {
    setAlanHatalari((mevcut) => (mevcut[alan] ? { ...mevcut, [alan]: null } : mevcut))
    setHata(null)
  }

  function kullaniciAdiDegisti(metin: string) {
    setKullaniciAdi(metin)
    alanHatasiniTemizle('kullaniciAdi')

    const normal = kullaniciAdiniNormallestir(metin)
    if (normal.length === 0) {
      setAdDurumu({ hal: 'bos' })
      return
    }
    if (!kullaniciAdiGecerliMi(normal)) {
      setAdDurumu({ hal: 'bicim' })
      return
    }
    setAdDurumu({ hal: 'kontrol' })
  }

  // Musaitlik sorgusu ayri bir etkide: her tusa basista degil, yazma
  // durunca bir kez calisiyor.
  useEffect(() => {
    if (adDurumu.hal !== 'kontrol') return
    const normal = kullaniciAdiniNormallestir(kullaniciAdi)
    const sira = ++sorguSirasi.current

    const zamanlayici = setTimeout(() => {
      kullaniciAdiMusaitMi(normal)
        .then((musait) => {
          if (sira !== sorguSirasi.current) return
          setAdDurumu({ hal: musait ? 'musait' : 'alinmis' })
        })
        .catch(() => {
          if (sira !== sorguSirasi.current) return
          // Ag hatasinda sessizce ipucuna donuyoruz: kullaniciya
          // "alinmis" demek yanlis olur, sunucu kaydederken zaten
          // benzersizligi zorluyor.
          setAdDurumu({ hal: 'bos' })
        })
    }, BEKLETME_MS)

    return () => clearTimeout(zamanlayici)
  }, [adDurumu.hal, kullaniciAdi])

  async function fotografSec() {
    const sonuc = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      quality: 0.7,
      allowsMultipleSelection: true,
      selectionLimit: EN_FAZLA_FOTOGRAF,
    })
    if (sonuc.canceled) return
    // Ekleme degil DEGISTIRME: onceki halde yanlis secilen bir fotograf
    // ekrandan bir daha cikarilamiyordu.
    setFotografUrileri(sonuc.assets.map((a) => a.uri).slice(0, EN_FAZLA_FOTOGRAF))
  }

  /** Uc alandan ISO tarih uretir; takvimde olmayan gunu reddeder. */
  function tarihiCoz(): string | null {
    if (gun.length === 0 || ay.length === 0 || yil.length !== 4) return null
    const g = Number(gun)
    const a = Number(ay)
    const y = Number(yil)
    if (!Number.isInteger(g) || !Number.isInteger(a) || !Number.isInteger(y)) return null
    if (a < 1 || a > 12 || g < 1 || g > 31 || y < 1900) return null

    const tarih = new Date(Date.UTC(y, a - 1, g))
    // 31 Subat gibi bir giris Date tarafindan sessizce kaydiriliyor;
    // geri okuyup ayni gun mu diye bakiyoruz.
    if (
      tarih.getUTCFullYear() !== y ||
      tarih.getUTCMonth() !== a - 1 ||
      tarih.getUTCDate() !== g
    ) {
      return null
    }
    const iki = (n: number) => String(n).padStart(2, '0')
    return `${y}-${iki(a)}-${iki(g)}`
  }

  async function devamEt() {
    setHata(null)
    const hatalar: Record<string, string | null> = {}

    if (ad.trim().length === 0) hatalar.ad = t('profilOlustur.adHata')

    const kullaniciAdiNormal = kullaniciAdiniNormallestir(kullaniciAdi)
    if (!kullaniciAdiGecerliMi(kullaniciAdiNormal)) {
      hatalar.kullaniciAdi = t('profilOlustur.kullaniciAdiIpucu')
    } else if (adDurumu.hal === 'alinmis') {
      hatalar.kullaniciAdi = t('profilOlustur.kullaniciAdiAlinmis')
    }

    const dogumTarihi = tarihiCoz()
    if (!dogumTarihi) {
      hatalar.dogum = t('profilOlustur.dogumHataGecersiz')
    } else if (onSekizAltindaMi(new Date(dogumTarihi))) {
      hatalar.dogum = t('profilOlustur.dogumHataYas')
    }

    setAlanHatalari(hatalar)
    if (Object.values(hatalar).some(Boolean)) return

    setGonderiliyor(true)
    try {
      const { data: kullaniciVerisi } = await supabase.auth.getUser()
      const kullaniciId = kullaniciVerisi.user?.id

      if (!kullaniciId) {
        setHata(t('profilOlustur.oturumDustu'))
        return
      }

      const fotografYollari: string[] = []
      for (const uri of fotografUrileri) {
        const yol = await fotografYukle(kullaniciId, uri)
        fotografYollari.push(yol)
      }

      const { error } = await supabase.from('profiller').insert({
        id: kullaniciId,
        ad: ad.trim(),
        kullanici_adi: kullaniciAdiNormal,
        dogum_tarihi: dogumTarihi,
        biyografi: biyografi.trim() || null,
        fotograflar: fotografYollari,
      })

      if (error) {
        if (error.code === '23505') {
          setAlanHatalari({ kullaniciAdi: t('profilOlustur.kullaniciAdiAlinmis') })
          setAdDurumu({ hal: 'alinmis' })
        } else {
          setHata(error.message)
        }
        return
      }

      await profilKontrolunuYenile()
      router.replace('/')
    } catch (hataNesnesi) {
      setHata(
        hataNesnesi instanceof Error
          ? hataNesnesi.message
          : t('profilOlustur.beklenmeyenHata')
      )
    } finally {
      setGonderiliyor(false)
    }
  }

  const kullaniciAdiHatali = Boolean(alanHatalari.kullaniciAdi) || adDurumu.hal === 'alinmis'

  return (
    <ScrollView
      style={stiller.sayfa}
      contentContainerStyle={stiller.icerik}
      keyboardShouldPersistTaps="handled"
    >
      <Text style={stiller.baslik}>{t('profilOlustur.baslik')}</Text>
      <Text style={stiller.altYazi}>{t('profilOlustur.altYazi')}</Text>

      {/* Fotograf: metin kutusu degil, gercekten fotografin durdugu yer. */}
      <View style={stiller.fotografAlani}>
        <Pressable
          onPress={fotografSec}
          accessibilityRole="button"
          accessibilityLabel={t('profilOlustur.fotografEkle')}
          style={stiller.avatarBasilir}
        >
          <View style={[stiller.avatar, fotografUrileri.length === 0 && stiller.avatarBos]}>
            {fotografUrileri[0] ? (
              <Image source={{ uri: fotografUrileri[0] }} style={stiller.avatarGorsel} />
            ) : (
              <Svg width={30} height={30} viewBox="0 0 24 24">
                <Path
                  d="M4 8.5A1.5 1.5 0 0 1 5.5 7h2L9 5h6l1.5 2h2A1.5 1.5 0 0 1 20 8.5v9A1.5 1.5 0 0 1 18.5 19h-13A1.5 1.5 0 0 1 4 17.5v-9Z"
                  stroke={renk.metinSoluk}
                  strokeWidth={1.6}
                  strokeLinejoin="round"
                  fill="none"
                />
                <Circle
                  cx={12}
                  cy={13}
                  r={3.2}
                  stroke={renk.metinSoluk}
                  strokeWidth={1.6}
                  fill="none"
                />
              </Svg>
            )}
          </View>
          <View style={stiller.rozet}>
            <Svg width={14} height={14} viewBox="0 0 24 24">
              <Path
                d="M12 5v14M5 12h14"
                stroke="#FFFFFF"
                strokeWidth={2.6}
                strokeLinecap="round"
              />
            </Svg>
          </View>
        </Pressable>

        <Pressable onPress={fotografSec} accessibilityRole="button" hitSlop={8}>
          <Text style={stiller.fotografYazi}>
            {fotografUrileri.length === 0
              ? t('profilOlustur.fotografEkle')
              : t('profilOlustur.fotografDegistir')}
          </Text>
        </Pressable>
        <Text style={stiller.fotografIpucu}>
          {fotografUrileri.length > 1
            ? t('profilOlustur.fotografSayisi', { sayi: fotografUrileri.length })
            : t('profilOlustur.fotografIpucu')}
        </Text>

        {fotografUrileri.length > 1 && (
          <View style={stiller.serit}>
            {fotografUrileri.slice(1).map((uri) => (
              <Image key={uri} source={{ uri }} style={stiller.seritKare} />
            ))}
          </View>
        )}
      </View>

      {/* Ad */}
      <Text style={stiller.etiket}>{t('profilOlustur.adEtiket')}</Text>
      <TextInput
        style={[
          stiller.girdi,
          odakli === 'ad' && stiller.girdiOdakli,
          Boolean(alanHatalari.ad) && stiller.girdiHatali,
        ]}
        placeholder={t('profilOlustur.adYerTutucu')}
        placeholderTextColor={renk.metinSoluk}
        value={ad}
        onChangeText={(yeni) => {
          setAd(yeni)
          alanHatasiniTemizle('ad')
        }}
        onFocus={() => setOdakli('ad')}
        onBlur={() => setOdakli(null)}
      />
      {alanHatalari.ad ? <Text style={stiller.alanHatasi}>{alanHatalari.ad}</Text> : null}

      {/* Kullanici adi */}
      <Text style={stiller.etiket}>{t('profilOlustur.kullaniciAdiEtiket')}</Text>
      <View
        style={[
          stiller.girdi,
          stiller.onekliGirdi,
          odakli === 'kullaniciAdi' && stiller.girdiOdakli,
          kullaniciAdiHatali && stiller.girdiHatali,
        ]}
      >
        <Text style={stiller.onek}>@</Text>
        <TextInput
          style={stiller.onekliYazi}
          placeholder={t('profilOlustur.kullaniciAdiYerTutucu')}
          placeholderTextColor={renk.metinSoluk}
          autoCapitalize="none"
          autoCorrect={false}
          value={kullaniciAdi}
          onChangeText={kullaniciAdiDegisti}
          onFocus={() => setOdakli('kullaniciAdi')}
          onBlur={() => setOdakli(null)}
        />
        {adDurumu.hal === 'musait' && (
          <Svg width={18} height={18} viewBox="0 0 24 24">
            <Path
              d="M5 12.5l4.5 4.5L19 7.5"
              stroke={renk.metin}
              strokeWidth={2.2}
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
          </Svg>
        )}
      </View>
      {/* Musaitlik sonucuna AYRILMIS yer: satir her durumda duruyor,
          sonuc gelince ekran ziplayarak buyumuyor. */}
      <Text
        style={[
          stiller.ipucu,
          (adDurumu.hal === 'alinmis' || Boolean(alanHatalari.kullaniciAdi)) &&
            stiller.ipucuHatali,
        ]}
      >
        {alanHatalari.kullaniciAdi
          ? alanHatalari.kullaniciAdi
          : adDurumu.hal === 'kontrol'
            ? t('profilOlustur.kullaniciAdiKontrol')
            : adDurumu.hal === 'musait'
              ? t('profilOlustur.kullaniciAdiMusait')
              : adDurumu.hal === 'alinmis'
                ? t('profilOlustur.kullaniciAdiAlinmis')
                : t('profilOlustur.kullaniciAdiIpucu')}
      </Text>

      {/* Dogum tarihi */}
      <Text style={stiller.etiket}>{t('profilOlustur.dogumEtiket')}</Text>
      <View style={stiller.tarihSatiri}>
        <TextInput
          style={[
            stiller.girdi,
            stiller.tarihKutusu,
            odakli === 'gun' && stiller.girdiOdakli,
            Boolean(alanHatalari.dogum) && stiller.girdiHatali,
          ]}
          placeholder={t('profilOlustur.dogumGun')}
          placeholderTextColor={renk.metinSoluk}
          keyboardType="number-pad"
          maxLength={2}
          value={gun}
          onChangeText={(yeni) => {
            const temiz = yeni.replace(/\D/g, '')
            setGun(temiz)
            alanHatasiniTemizle('dogum')
            if (temiz.length === 2) ayRef.current?.focus()
          }}
          onFocus={() => setOdakli('gun')}
          onBlur={() => setOdakli(null)}
        />
        <TextInput
          ref={ayRef}
          style={[
            stiller.girdi,
            stiller.tarihKutusu,
            odakli === 'ay' && stiller.girdiOdakli,
            Boolean(alanHatalari.dogum) && stiller.girdiHatali,
          ]}
          placeholder={t('profilOlustur.dogumAy')}
          placeholderTextColor={renk.metinSoluk}
          keyboardType="number-pad"
          maxLength={2}
          value={ay}
          onChangeText={(yeni) => {
            const temiz = yeni.replace(/\D/g, '')
            setAy(temiz)
            alanHatasiniTemizle('dogum')
            if (temiz.length === 2) yilRef.current?.focus()
          }}
          onFocus={() => setOdakli('ay')}
          onBlur={() => setOdakli(null)}
        />
        <TextInput
          ref={yilRef}
          style={[
            stiller.girdi,
            stiller.tarihKutusu,
            stiller.yilKutusu,
            odakli === 'yil' && stiller.girdiOdakli,
            Boolean(alanHatalari.dogum) && stiller.girdiHatali,
          ]}
          placeholder={t('profilOlustur.dogumYil')}
          placeholderTextColor={renk.metinSoluk}
          keyboardType="number-pad"
          maxLength={4}
          value={yil}
          onChangeText={(yeni) => {
            setYil(yeni.replace(/\D/g, ''))
            alanHatasiniTemizle('dogum')
          }}
          onFocus={() => setOdakli('yil')}
          onBlur={() => setOdakli(null)}
        />
      </View>
      <Text style={[stiller.ipucu, Boolean(alanHatalari.dogum) && stiller.ipucuHatali]}>
        {alanHatalari.dogum ?? t('profilOlustur.dogumIpucu')}
      </Text>

      {/* Biyografi */}
      <View style={stiller.etiketSatiri}>
        <Text style={stiller.etiket}>{t('profilOlustur.biyografiEtiket')}</Text>
        <Text style={stiller.istegeBagli}>{t('profilOlustur.istegeBagli')}</Text>
      </View>
      <TextInput
        style={[
          stiller.girdi,
          stiller.cokSatirli,
          odakli === 'biyografi' && stiller.girdiOdakli,
        ]}
        placeholder={t('profilOlustur.biyografiYerTutucu')}
        placeholderTextColor={renk.metinSoluk}
        value={biyografi}
        onChangeText={setBiyografi}
        onFocus={() => setOdakli('biyografi')}
        onBlur={() => setOdakli(null)}
        multiline
      />

      {hata && <Text style={stiller.hata}>{hata}</Text>}

      <Pressable
        style={stiller.birincil}
        onPress={devamEt}
        disabled={gonderiliyor}
        accessibilityRole="button"
      >
        <Text style={stiller.birincilYazi}>
          {gonderiliyor ? t('profilOlustur.gonderiliyor') : t('profilOlustur.gonder')}
        </Text>
      </Pressable>
    </ScrollView>
  )
}

