import puppeteer from 'puppeteer-core'

const CHROME =
  'C:' +
  String.fromCharCode(92) +
  'Program Files' +
  String.fromCharCode(92) +
  'Google' +
  String.fromCharCode(92) +
  'Chrome' +
  String.fromCharCode(92) +
  'Application' +
  String.fromCharCode(92) +
  'chrome.exe'

const NL = String.fromCharCode(10)
const telefon = process.env.TEL || '05550000003'

const t = await puppeteer.launch({
  executablePath: CHROME,
  headless: true,
  args: ['--no-sandbox', '--disable-gpu'],
})
const s = await t.newPage()
await s.setViewport({
  width: 390,
  height: 844,
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
})

async function bas(metin) {
  const ogeler = await s.$$('[role="button"]')
  for (const o of ogeler) {
    const y = await s.evaluate((el) => el.textContent || '', o)
    if (y.includes(metin)) {
      await o.click()
      return true
    }
  }
  return false
}

async function ekran(etiket) {
  const metin = await s.evaluate(() => document.body.innerText)
  console.log(etiket, s.url())
  console.log('   ', JSON.stringify(metin.split(NL).filter(Boolean).slice(0, 4)))
}

await s.goto('http://127.0.0.1:8080/', { waitUntil: 'networkidle0', timeout: 60000 })
await new Promise((r) => setTimeout(r, 2500))
await bas('Hesap oluştur')
await new Promise((r) => setTimeout(r, 2500))

const alanlar = await s.$$('input')
await alanlar[0].type(telefon, { delay: 15 })
await bas('Kodu gönder')
await new Promise((r) => setTimeout(r, 6000))

const kodAlanlari = await s.$$('input')
if (kodAlanlari.length > 0) await kodAlanlari[0].type('123456', { delay: 40 })
await new Promise((r) => setTimeout(r, 9000))
await ekran('kod girildikten sonra (' + telefon + '):')

if (process.argv[2]) await s.screenshot({ path: process.argv[2] })
await t.close()

